schema_ddl:
CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    codice_fiscale TEXT NOT NULL UNIQUE,
    data_nascita DATE,
    indirizzo TEXT
);

CREATE TABLE ordini (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    data_ordine TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    importo_totale NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (importo_totale >= 0),
    stato TEXT NOT NULL DEFAULT 'pending' CHECK (stato IN ('pending', 'processing', 'shipped', 'delivered', 'cancelled'))
);

CREATE TABLE prodotti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    descrizione TEXT,
    prezzo_unitario NUMERIC(10,2) NOT NULL CHECK (prezzo_unitario >= 0),
    codice TEXT NOT NULL UNIQUE,
    attivo BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE dettagli_ordini (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ordine_id INT NOT NULL REFERENCES ordini(id),
    prodotto_id INT NOT NULL REFERENCES prodotti(id),
    quantita INT NOT NULL CHECK (quantita > 0),
    prezzo_unitario NUMERIC(10,2) NOT NULL CHECK (prezzo_unitario >= 0)
);

CREATE INDEX idx_ordini_cliente_id ON ordini(cliente_id);

CREATE INDEX idx_dettagli_ordini_ordine_id ON dettagli_ordini(ordine_id);

CREATE INDEX idx_dettagli_ordini_prodotto_id ON dettagli_ordini(prodotto_id);
